"""Read pending LLM calls, halted author jobs, and budget inflight counts."""
import json
import re
import sys
from pathlib import Path


def reject_constant(value):
    raise ValueError('not a JSON constant: ' + value)


def read_object(path):
    try:
        value = json.loads(path.read_text(encoding='utf-8'), parse_constant=reject_constant)
    except (OSError, UnicodeError, ValueError):
        return None
    return value if isinstance(value, dict) else None


def directories(path):
    if not path.is_dir():
        return []
    return (child for child in path.iterdir() if child.is_dir())


def collect(node):
    pending = []
    for budget in directories(node / 'llmcall'):
        for call in directories(budget):
            if read_object(call / 'request.json') is None:
                continue
            if (call / 'receipt.json').exists():
                continue
            pending.append({
                'budget': budget.name,
                'call_id': call.name,
                'stage': 'raw' if (call / 'raw.json').exists() else 'request',
            })

    halted = []
    for job in directories(node / 'jobs'):
        if re.fullmatch(r'.+_[0-9a-fA-F]{8}', job.name, flags=re.DOTALL) is None:
            continue
        rid = job.name[:-9]
        if not (node / 'author' / 'req' / rid).is_dir():
            continue
        frame = read_object(job / 'frame.json')
        if frame is None or frame.get('phase') != 'halted':
            continue
        halt = frame.get('halt')
        halt = halt if isinstance(halt, dict) else {}
        halted.append({
            'job': job.name, 'rid': rid,
            'kind': halt.get('kind'), 'why': halt.get('why'),
        })

    inflight = []
    for budget in directories(node / 'budget'):
        ledger = read_object(budget / 'ledger.json')
        if ledger is None:
            continue
        count = ledger.get('inflight')
        if type(count) is int and count > 0:
            inflight.append({'budget': budget.name, 'inflight': count})

    pending.sort(key=lambda row: (row['budget'], row['call_id'], row['stage']))
    halted.sort(key=lambda row: row['job'])
    inflight.sort(key=lambda row: row['budget'])
    return {'v': 1, 'llmcall_pending': pending,
            'author_halted': halted, 'budget_inflight': inflight}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1 or not Path(args[0]).is_dir():
        print('usage: aos7-llmdiag <node directory>', file=sys.stderr)
        return 2
    print(json.dumps(collect(Path(args[0])), ensure_ascii=False))
    return 0
